-- Generated by the Neutrino Translator from verified MLIR.
-- Idempotent + atomic (a function body runs in a single transaction).
CREATE OR REPLACE FUNCTION attest_token_mint(p_mint_id text)
RETURNS void
LANGUAGE plpgsql
AS $$
BEGIN
    IF EXISTS (SELECT 1 FROM coordination_status WHERE idempotency_key = p_mint_id AND procedure = 'token_mint' AND reconciled) THEN
        RAISE EXCEPTION 'bad transition';
    END IF;
    INSERT INTO coordination_status(procedure, idempotency_key, attested) VALUES ('token_mint', p_mint_id, true)
    ON CONFLICT (procedure, idempotency_key) DO UPDATE SET attested = true;
END;
$$;

CREATE OR REPLACE FUNCTION execute_token_mint(p_mint_id text, p_supply_id text, p_holder_id text, p_amount bigint, p_currency text, p_supply_approved bigint)
RETURNS void
LANGUAGE plpgsql
AS $$
DECLARE
    -- (no computed values)
BEGIN
    IF EXISTS (SELECT 1 FROM coordination_status WHERE idempotency_key = p_mint_id AND procedure = 'token_mint' AND reconciled) THEN
        RAISE EXCEPTION 'replay';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM coordination_status WHERE idempotency_key = p_mint_id AND procedure = 'token_mint' AND attested) THEN
        RAISE EXCEPTION 'missing attestation';
    END IF;

    -- idempotency guard (replay-safe): one row per workflow key
    INSERT INTO posting_idempotency(idempotency_key, entry)
    VALUES (p_mint_id, 'token_mint')
    ON CONFLICT DO NOTHING;
    IF NOT FOUND THEN
        RETURN;  -- already processed; no double posting
    END IF;


    -- debit supply_debit (token.supply) when p_supply_approved = 1
    IF p_supply_approved = 1 THEN
    IF (p_amount) < 0 THEN
        RAISE EXCEPTION 'negative money for supply_debit';
    END IF;
    INSERT INTO ledger_balance(ledger, party, currency, balance)
    VALUES ('token.supply', p_supply_id, p_currency, -(p_amount))
    ON CONFLICT (ledger, party, currency)
    DO UPDATE SET balance = ledger_balance.balance + (-(p_amount));
    INSERT INTO postings(procedure, entry, ledger, party, amount, currency, signed_amount, idempotency_key)
    VALUES ('token_mint', 'supply_debit', 'token.supply', p_supply_id, p_amount, p_currency, -(p_amount), p_mint_id);
    END IF;

    -- credit holder_credit (token.balance) when p_supply_approved = 1
    IF p_supply_approved = 1 THEN
    IF (p_amount) < 0 THEN
        RAISE EXCEPTION 'negative money for holder_credit';
    END IF;
    INSERT INTO ledger_balance(ledger, party, currency, balance)
    VALUES ('token.balance', p_holder_id, p_currency, p_amount)
    ON CONFLICT (ledger, party, currency)
    DO UPDATE SET balance = ledger_balance.balance + (p_amount);
    INSERT INTO postings(procedure, entry, ledger, party, amount, currency, signed_amount, idempotency_key)
    VALUES ('token_mint', 'holder_credit', 'token.balance', p_holder_id, p_amount, p_currency, p_amount, p_mint_id);
    END IF;

    -- balanced invariant: this workflow key must net to zero
    IF (SELECT COALESCE(SUM(signed_amount), 0) FROM postings WHERE procedure = 'token_mint' AND idempotency_key = p_mint_id) <> 0 THEN
        RAISE EXCEPTION 'not balanced for %', p_mint_id;
    END IF;

    INSERT INTO coordination_status(procedure, idempotency_key, reconciled) VALUES ('token_mint', p_mint_id, true)
    ON CONFLICT (procedure, idempotency_key) DO UPDATE SET reconciled = true;
END;
$$;
